import React, { useCallback, useEffect, useState } from 'react';
import { Button, Col, Row } from 'react-bootstrap';
import { useParams } from 'react-router-dom';
import Dialog from '@mui/material/Dialog';
import DialogTitle from '@mui/material/DialogTitle';
import DialogContent from '@mui/material/DialogContent';
import IconButton from '@mui/material/IconButton';
import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableHead from '@mui/material/TableHead';
import TableRow from '@mui/material/TableRow';
import Paper from '@mui/material/Paper';
import CloseIcon from '@mui/icons-material/Close';
import PropTypes from 'prop-types';
import DialogActions from '@mui/material/DialogActions';
import { styled } from '@mui/material/styles';
import FormGroup from '@mui/material/FormGroup';
import FormControl from '@mui/material/FormControl';
import MenuItem from '@mui/material/MenuItem';
import Select from '@mui/material/Select';
import ListSubheader from '@mui/material/ListSubheader';
import TextField from '@mui/material/TextField';
import { useDispatch, useSelector } from 'react-redux';
import {
  getBookingCouponAvailableList,
  getCouponListData,
} from 'store/reducers/Admin/Events/Coupon/Coupons/coupon.slice';
import moment from 'moment';
import {
  createBookingCoupon,
  deleteBookingCoupon,
  getBookingCouponData,
  getBookingCouponListData,
  processCoupon,
  updateBookingCoupon,
} from 'store/reducers/Booking/bookingCoupon.slice';
import Checkbox from '@mui/material/Checkbox';
import FormControlLabel from '@mui/material/FormControlLabel';
import EditIcon from '../../Assets/Img/edit.svg';

import CheckIcon from '../../Assets/Img/check-green.svg';
import CrossIcon from '../../Assets/Img/cross-red.svg';
import HoldDate from '../../Assets/Img/hold-date.svg';
import RemoveCircleOutlineIcon from '@mui/icons-material/RemoveCircleOutline';
import Loader from 'Components/Common/Loader';
import { Form, Formik } from 'formik';
import { getEnquiriesData } from 'store/reducers/Enquiry/enquiries.slice';

const BootstrapDialog = styled(Dialog)(({ theme }) => ({
  '& .MuiDialogContent-root': {
    padding: theme.spacing(2),
  },
  '& .MuiDialogActions-root': {
    padding: theme.spacing(1),
  },
}));

function BootstrapDialogTitle(props) {
  const { children, onClose, ...other } = props;

  return (
    <DialogTitle sx={{ m: 0, p: 2 }} {...other}>
      {children}
      {onClose ? (
        <IconButton
          aria-label="close"
          onClick={onClose}
          sx={{
            position: 'absolute',
            right: 19,
            top: 19,
            color: theme => theme.palette.grey[600],
          }}
        >
          <CloseIcon />
        </IconButton>
      ) : null}
    </DialogTitle>
  );
}

BootstrapDialogTitle.propTypes = {
  children: PropTypes.node,
  onClose: PropTypes.func.isRequired,
};

export default function CouponsInfo({ enquirieDetail, id }) {
  const dispatch = useDispatch();
  const { bookingId } = useParams();

  const { getBookingCouponAvailableData } = useSelector(({ coupon }) => coupon);
  const { userPermissionDetail } = useSelector(({ user }) => user);

  const [addCouponPopup, setAddCouponPopup] = useState(false);
  const [editCouponPopup, setEditCouponPopup] = useState(false);
  const {
    bookingCouponList,
    bookingCouponLoading,
    bookingCouponDetail,
    isBookingCouponUpdated,
  } = useSelector(({ bookingCoupon }) => bookingCoupon);

  //create coupon make without Formik and updateCoupon has used Formik
  const initialValueUpdateBookingCoupon = {
    coupon: [],
    is_accepted: false,
    is_processed: false,
    is_rejected: false,
    reject_note: '',
    note: '',
  };
  const [bookingCouponData, setBookingCouponData] = useState(
    initialValueUpdateBookingCoupon,
  );

  const [errorMessage, setErrorMessage] = useState('');

  const [couponId, setCouponId] = useState('');
  const [initialState, setInitialState] = useState({
    booking_id: enquirieDetail._id,
    coupon_id: '',
    note: '',
  });
  const handleChange = e => {
    const { name, value } = e.target;
    setInitialState(prevState => ({
      ...prevState,
      [name]: value,
      booking_id: enquirieDetail._id,
    }));
  };
  // useEffect(() => {
  //   dispatch(getCouponListData());
  // }, [dispatch]);

  useEffect(() => {
    if (Object.keys(enquirieDetail).length && enquirieDetail?.is_booking)
      dispatch(getBookingCouponAvailableList(id));
  }, [dispatch, enquirieDetail]);

  useEffect(() => {
    if (id && Object.keys(enquirieDetail).length) {
      if (enquirieDetail?.is_booking)
        dispatch(getBookingCouponListData({ _id: id }));
    }
  }, [dispatch, id, enquirieDetail]);

  useEffect(() => {
    if (isBookingCouponUpdated) {
      dispatch(getBookingCouponListData({ _id: bookingId }));
    }
  }, [isBookingCouponUpdated]);

  const OpenAddCoupon = () => {
    setAddCouponPopup(true);
  };
  const OpenEditCoupon = () => {
    setEditCouponPopup(true);
  };
  const CloseAddCoupon = () => {
    setErrorMessage('');
    setAddCouponPopup(false);
  };
  const CloseEditCoupon = () => {
    setEditCouponPopup(false);
  };

  const handleSubmite = () => {
    if (couponId === '') {
      setErrorMessage('Please select an atleast one coupon');
    } else {
      setErrorMessage('');
      dispatch(createBookingCoupon(initialState));
      setAddCouponPopup(false);
      setInitialState({});
      setCouponId('');
    }
  };
  // const couonOptions = useCallback(() => {
  //   let couponsData = [];
  //   let finalCoupon = [
  //     ...getBookingCouponAvailableData?.active_coupon,
  //     ...getBookingCouponAvailableData?.expired_coupon,
  //   ];
  //   const activeCouponsHeader = <ListSubheader>--- Active ---</ListSubheader>;
  //   const expireCouponsHeader = <ListSubheader>--- Expire ---</ListSubheader>;

  //   if (finalCoupon?.length > 0 && Object.keys(enquirieDetail)?.length > 0) {
  //     let activeCoupons = [];
  //     let expireCoupons = [];
  //     let d =
  //       bookingCouponList.map(item => {
  //         return item?.coupon_id;
  //       }) || [];
  //     finalCoupon?.map(
  //       data =>
  //         !d.includes(data?._id) &&
  //         data?.available_at_events?.map(item =>
  //           item?.event_id === enquirieDetail?.event_info?._id
  //             ? moment(new Date()).format('YYYY/MM/DD') < // before current year > expire date
  //               moment(data?.expires_after).format('YYYY/MM/DD')
  //               ? activeCoupons.push(
  //                   <MenuItem value={data?._id}>{data?.sku}</MenuItem>,
  //                 )
  //               : expireCoupons.push(
  //                   <MenuItem value={data?._id}>{data?.sku}</MenuItem>,
  //                 )
  //             : null,
  //         ),
  //     );

  //     couponsData = [
  //       activeCouponsHeader,
  //       ...activeCoupons,
  //       expireCouponsHeader,
  //       ...expireCoupons,
  //     ];
  //   } else {
  //     couponsData = [activeCouponsHeader, expireCouponsHeader];
  //   }
  //   return couponsData;
  // }, [activeCouponList, inActiveCouponList, enquirieDetail, bookingCouponList]);

  useEffect(() => {
    if (Object.values(bookingCouponDetail)?.length > 0) {
      setBookingCouponData({
        coupon: bookingCouponDetail?.coupon ? bookingCouponDetail?.coupon : '',
        is_accepted: bookingCouponDetail?.is_accepted
          ? bookingCouponDetail?.is_accepted
          : false,
        is_processed: bookingCouponDetail?.is_processed
          ? bookingCouponDetail?.is_processed
          : false,
        is_rejected: bookingCouponDetail?.is_rejected
          ? bookingCouponDetail?.is_rejected
          : false,
        reject_note: bookingCouponDetail?.reject_note
          ? bookingCouponDetail?.reject_note
          : '',
        note: bookingCouponDetail?.note ? bookingCouponDetail?.note : '',
        booking_id: bookingCouponDetail?.booking_id
          ? bookingCouponDetail?.booking_id
          : '',
        coupon_id: bookingCouponDetail?.coupon_id
          ? bookingCouponDetail?.coupon_id
          : '',
      });
    }
  }, [bookingCouponDetail]);

  return (
    <>
      <div className="card_wrapper mb-4">
        {bookingCouponLoading && <Loader />}
        <div className="card_header d-flex align-items-center justify-content-between py-2 px-3">
          <h4 className="m-0 py-1 text_white">Coupons</h4>
          <Button className="btn_border small" onClick={OpenAddCoupon}>
            Add Coupon
          </Button>
        </div>
        <div className="card_body">
          {bookingCouponList?.length > 0 ? (
            <ul>
              <li>
                <div className="no_data w-100">
                  <div className="bg_gray_box table_main_Wrapper">
                    <TableContainer component={Paper}>
                      <Table sx={{ minWidth: 650 }} aria-label="simple table">
                        <TableHead>
                          <TableRow>
                            <TableCell>Date</TableCell>
                            <TableCell>Deposit Required</TableCell>
                            <TableCell>Accepted</TableCell>
                            <TableCell>
                              <span>Sku Name</span>
                            </TableCell>
                            <TableCell>
                              <span>Name</span>
                            </TableCell>
                            <TableCell>Processed</TableCell>
                          </TableRow>
                        </TableHead>
                        <TableBody>
                          {bookingCouponList?.map(data => {
                            return (
                              <>
                                <TableRow
                                  className={
                                    data?.is_rejected === true && `bg_highlight`
                                  }
                                >
                                  <TableCell>
                                    <img
                                      src={HoldDate}
                                      alt="Chat icon"
                                      className="me-2 icon_grayscale"
                                      data-toggle="tooltip"
                                      data-placement="bottom"
                                      title={`Added by ${
                                        data?.created_by?.name
                                      } ${data?.created_by?.username} ${`on ${
                                        data?.created_at
                                          ? moment(
                                              // .utc(data?.created_at)
                                              data?.created_at,
                                            ).format(
                                              'dddd DD MMMM YYYY - HH:mm:ss ',
                                            )
                                          : ''
                                      }`} 
                                        `}
                                    />
                                  </TableCell>
                                  <TableCell>
                                    {data?.deposits_required_by !== null ||
                                    '' ? (
                                      data?.is_payment_paid === true ? (
                                        <img
                                          src={CheckIcon}
                                          alt="Check Icon"
                                          data-toggle="tooltip"
                                          data-placement="bottom"
                                          title={`paid`}
                                        />
                                      ) : (
                                        <img
                                          src={CrossIcon}
                                          alt="Cross Icon"
                                          data-toggle="tooltip"
                                          data-placement="bottom"
                                          title={`A Deposite is requied by ${moment
                                            .utc(data?.deposits_required_by)
                                            .format(
                                              'YYYY-MM-DD',
                                            )} but NOT yet paid`}
                                        />
                                      )
                                    ) : (
                                      <div
                                        data-toggle="tooltip"
                                        data-placement="bottom"
                                        title={`A Deposite is not required for this coupon`}
                                      >
                                        <RemoveCircleOutlineIcon fontSize="medium" />
                                      </div>
                                    )}
                                  </TableCell>
                                  <TableCell>
                                    {data?.is_accepted === true ? (
                                      <img
                                        src={CheckIcon}
                                        alt="Check Icon"
                                        data-toggle="tooltip"
                                        data-placement="bottom"
                                        title={`Accepted by ${
                                          data?.created_by?.name
                                        } ${data?.created_by?.username} ${`on ${
                                          data?.created_at
                                            ? moment
                                                .utc(data?.created_at)
                                                .format(
                                                  'dddd DD MMMM YYYY - HH:mm:ss ',
                                                )
                                            : ''
                                        }`} 
                                        `}
                                      />
                                    ) : (
                                      <img
                                        src={CrossIcon}
                                        alt="Cross Icon "
                                        data-toggle="tooltip"
                                        data-placement="bottom"
                                        title={`This coupon has not been accepted yet`}
                                      />
                                    )}
                                  </TableCell>
                                  <TableCell>
                                    {data?.is_rejected === true ? (
                                      <del className="m-0">{data?.sku}</del>
                                    ) : (
                                      <p className="m-0">{data?.sku}</p>
                                    )}
                                  </TableCell>
                                  <TableCell>
                                    {data?.is_rejected === true ? (
                                      <del className="m-0">{data?.name}</del>
                                    ) : (
                                      <p className="m-0">{data?.name}</p>
                                    )}
                                  </TableCell>
                                  <TableCell>
                                    {data?.is_processed === true ? (
                                      <img
                                        src={CheckIcon}
                                        alt="Check Icon"
                                        data-toggle="tooltip"
                                        data-placement="bottom"
                                        title={`Processed by ${
                                          data?.created_by?.name
                                        } ${data?.created_by?.username} ${`on ${
                                          data?.created_at
                                            ? moment
                                                .utc(data?.created_at)
                                                .format(
                                                  'dddd DD MMMM YYYY - HH:mm:ss ',
                                                )
                                            : ''
                                        }`} 
                                      `}
                                      />
                                    ) : (
                                      <img
                                        src={CrossIcon}
                                        alt="Cross Icon"
                                        data-toggle="tooltip"
                                        data-placement="bottom"
                                        title={`Not Processed yet`}
                                      />
                                    )}
                                  </TableCell>
                                  <TableCell>
                                    {userPermissionDetail?.processcoupons &&
                                      userPermissionDetail?.admin &&
                                      userPermissionDetail?.super && (
                                        <Button
                                          className="btn_edit"
                                          onClick={() => {
                                            OpenEditCoupon();
                                            dispatch(
                                              getBookingCouponData({
                                                _id: data?._id,
                                              }),
                                            );
                                          }}
                                        >
                                          <img src={EditIcon} alt="Edit Icon" />
                                        </Button>
                                      )}
                                  </TableCell>
                                </TableRow>
                              </>
                            );
                          })}
                        </TableBody>
                      </Table>
                    </TableContainer>
                  </div>
                  {enquirieDetail?.is_process_coupons && ( // pavan will add new flag for is_process_coupons
                    <>
                      {userPermissionDetail?.processcoupons &&
                        userPermissionDetail?.admin &&
                        userPermissionDetail?.super && (
                          <ul className="d-flex mt-2 align-items-center justify-content-center">
                            <li>
                              <Button
                                className="btn_primary small mx-2"
                                onClick={() =>
                                  dispatch(processCoupon({ booking_id: id }))
                                }
                              >
                                Process Coupons
                              </Button>
                            </li>
                          </ul>
                        )}
                    </>
                  )}
                </div>
              </li>
            </ul>
          ) : (
            <ul>
              <li>
                <div className="no_data">
                  <p className="m-0 py-2 text_light">No coupons assigned</p>
                </div>
              </li>
            </ul>
          )}
        </div>
      </div>

      <BootstrapDialog
        aria-labelledby="CancelBooking-title"
        open={addCouponPopup}
        className="small_popup"
      >
        <BootstrapDialogTitle id="CancelBooking-title" onClose={CloseAddCoupon}>
          Add Coupon
        </BootstrapDialogTitle>
        <DialogContent dividers>
          <div className="popup_content_wrap">
            {getBookingCouponAvailableData?.active_coupon?.length > 0 ||
            getBookingCouponAvailableData?.expired_coupon?.length > 0 ? (
              <>
                <ul>
                  <li className="bg_gray_box px-3 py-2 mb-2">
                    <Row className="align-items-center">
                      <Col>
                        <label>Select Coupon :</label>
                      </Col>
                      <Col>
                        <FormGroup className="input_wrap">
                          <FormControl>
                            <Select
                              defaultValue="Please Select"
                              id="grouped-select"
                              name="coupon_id"
                              value={couponId}
                              onChange={e => {
                                if (e.target.value !== '') {
                                  setErrorMessage('');
                                }
                                setCouponId(e.target.value);
                                handleChange(e);
                              }}
                            >
                              {/* {couonOptions()} */}
                              <ListSubheader>--- Active ---</ListSubheader>
                              {getBookingCouponAvailableData?.active_coupon?.map(
                                activeItem => {
                                  return (
                                    <MenuItem value={activeItem?._id}>
                                      {activeItem?.internal_name}
                                    </MenuItem>
                                  );
                                },
                              )}
                              <ListSubheader>--- Expire ---</ListSubheader>
                              {getBookingCouponAvailableData?.expired_coupon?.map(
                                activeItem => {
                                  return (
                                    <MenuItem value={activeItem?._id}>
                                      {activeItem?.internal_name}
                                    </MenuItem>
                                  );
                                },
                              )}
                            </Select>
                            {errorMessage !== '' && (
                              <span className="d-block text-danger text_small lookup_error">
                                {errorMessage}
                              </span>
                            )}
                          </FormControl>
                        </FormGroup>
                      </Col>
                    </Row>
                  </li>
                  <li className="bg_gray_box px-3 py-2 mb-2">
                    <Row className="align-items-start">
                      <Col>
                        <label>Coupon Note: (optional)</label>
                      </Col>
                      <Col>
                        <FormGroup className="input_wrap">
                          <FormControl fullWidth className="small_select">
                            <TextField
                              id="ContractReceived"
                              type="text"
                              multiline
                              rows={3}
                              variant="outlined"
                              className="input_wrap"
                              placeholder="Enter"
                              name="note"
                              onChange={handleChange}
                            />
                          </FormControl>
                        </FormGroup>
                      </Col>
                    </Row>
                  </li>
                </ul>
                <ul className="d-flex align-items-center justify-content-center">
                  <li>
                    <Button
                      className="btn_primary small mx-2"
                      onClick={handleSubmite}
                    >
                      Add Coupon
                    </Button>
                  </li>
                </ul>
              </>
            ) : (
              <ul>
                <li className="bg_gray_box px-3 py-2 mb-2">
                  <Row className="align-items-center">
                    <Col xs={4}>
                      <label>Select Coupon :</label>
                    </Col>
                    <Col xs={8}>
                      <FormGroup className="input_wrap">
                        <FormControl>
                          <TextField
                            type="text"
                            variant="outlined"
                            className="input_wrap"
                            value="Sorry, there are no coupons available for this booking"
                          />
                        </FormControl>
                      </FormGroup>
                    </Col>
                  </Row>
                </li>
              </ul>
            )}
          </div>
        </DialogContent>
        {/* <DialogActions className="justify-content-center mb-3"></DialogActions> */}
      </BootstrapDialog>

      <BootstrapDialog
        aria-labelledby="CancelBooking-title"
        open={editCouponPopup}
        className="small_popup"
      >
        {bookingCouponLoading && <Loader />}

        <BootstrapDialogTitle
          id="CancelBooking-title"
          onClose={CloseEditCoupon}
        >
          Edit Coupon
        </BootstrapDialogTitle>
        <Formik
          enableReinitialize={true}
          initialValues={bookingCouponData}
          onSubmit={async values => {
            let data = {
              ...values,
              reject_note:
                values?.is_rejected === true ? values?.reject_note : '',
            };
            setEditCouponPopup(false);
            await dispatch(
              updateBookingCoupon({
                _id: bookingCouponDetail?._id,
                bookingCoupon: data,
              }),
            );
            await dispatch(getEnquiriesData(bookingId));
          }}
        >
          {({
            handleSubmit,
            handleChange,
            setFieldValue,
            values,
            getFieldProps,
          }) => (
            <Form onSubmit={handleSubmit}>
              <DialogContent dividers>
                <div className="popup_content_wrap">
                  <ul>
                    <li className="bg_gray_box px-3 py-2 mb-2">
                      <Row className="align-items-center">
                        <Col>
                          <label>Coupon :</label>
                        </Col>
                        <Col>
                          <FormGroup>
                            <FormControl>
                              <p className="m-0">
                                {values?.coupon[0]?.sku} -{' '}
                                {values?.coupon[0]?.internal_name}
                              </p>
                            </FormControl>
                          </FormGroup>
                        </Col>
                      </Row>
                    </li>
                    <li className="bg_gray_box px-3 py-2 mb-2">
                      <Row className="align-items-center">
                        <Col>
                          <label>Mark as Accepted?: (optional) :</label>
                          <p>
                            If this coupon is valid please ensure this box is
                            ticked.
                          </p>
                        </Col>
                        <Col>
                          <FormGroup>
                            <FormControl>
                              <div className="form-group checkbox_wrap">
                                <FormGroup>
                                  <FormControlLabel
                                    control={
                                      <Checkbox
                                        name="is_accepted"
                                        checked={values.is_accepted}
                                        onClick={handleChange}
                                      />
                                    }
                                  />
                                </FormGroup>
                              </div>
                            </FormControl>
                          </FormGroup>
                        </Col>
                      </Row>
                    </li>
                    <li className="bg_gray_box px-3 py-2 mb-2">
                      <Row className="align-items-center">
                        <Col>
                          <label>Mark as Processed?: (optional)</label>
                          <p>
                            If this coupon has been processed please ensure this
                            box is ticked.
                          </p>
                        </Col>
                        <Col>
                          <FormGroup>
                            <FormControl>
                              <div className="form-group checkbox_wrap mb-2">
                                <FormGroup>
                                  <FormControlLabel
                                    control={
                                      <Checkbox
                                        name="is_processed"
                                        checked={values.is_processed}
                                        onClick={handleChange}
                                      />
                                    }
                                  />
                                </FormGroup>
                              </div>
                            </FormControl>
                          </FormGroup>
                        </Col>
                      </Row>
                    </li>
                    <li className="bg_gray_box px-3 py-2 mb-2">
                      <Row className="align-items-center">
                        <Col>
                          <label>Force Reject?: (optional)</label>
                          <p>
                            This will void this coupon against this booking and
                            ensure that the customer cannot re-add this coupon
                            via their online account.
                          </p>
                          <p>
                            Please add a note to explain why this coupon is
                            marked as reject.
                          </p>
                        </Col>
                        <Col>
                          <FormGroup>
                            <FormControl>
                              <div className="form-group checkbox_wrap mb-2">
                                <FormGroup>
                                  <FormControlLabel
                                    className="mb-3"
                                    control={
                                      <Checkbox
                                        name="is_rejected"
                                        checked={values.is_rejected}
                                        onClick={handleChange}
                                      />
                                    }
                                  />
                                  {/* {values.is_rejected === true && ( */}
                                  <FormControl className="small_select">
                                    <TextField
                                      id="ContractReceived"
                                      type="text"
                                      multiline
                                      rows={3}
                                      variant="outlined"
                                      placeholder="Enter"
                                      name="reject_note"
                                      value={values.reject_note}
                                      onChange={handleChange}
                                    />
                                  </FormControl>
                                  {/* )} */}
                                </FormGroup>
                              </div>
                            </FormControl>
                          </FormGroup>
                        </Col>
                      </Row>
                    </li>
                    <li className="bg_gray_box px-3 py-2 mb-2">
                      <Row className="align-items-start">
                        <Col>
                          <label>Coupon Note: (internal / optional)</label>
                        </Col>
                        <Col>
                          <FormGroup>
                            <FormControl fullWidth className="small_select">
                              <TextField
                                id="ContractReceived"
                                type="text"
                                multiline
                                rows={3}
                                variant="outlined"
                                className="input_wrap"
                                placeholder="Enter"
                                name="note"
                                value={values.note}
                                onChange={handleChange}
                              />
                            </FormControl>
                          </FormGroup>
                        </Col>
                      </Row>
                    </li>
                  </ul>
                </div>
              </DialogContent>
              <DialogActions className="justify-content-center mb-3">
                <ul className="d-flex align-items-center justify-content-center">
                  <li>
                    <Button className="btn_primary small mx-2" type="submit">
                      Update Coupon
                    </Button>
                  </li>
                  {(bookingCouponDetail?.is_accepted ||
                    bookingCouponDetail?.is_processed) === false && (
                    <li>
                      <Button
                        className="btn_primary small mx-2"
                        onClick={() => {
                          dispatch(
                            deleteBookingCoupon(bookingCouponDetail?._id),
                          );
                          setEditCouponPopup(false);
                        }}
                      >
                        Remove Coupon
                      </Button>
                    </li>
                  )}
                </ul>
              </DialogActions>
            </Form>
          )}
        </Formik>
      </BootstrapDialog>
    </>
  );
}
