import { useEffect, useState } from 'react';
import moment from 'moment';
import { Col, Row } from 'react-bootstrap';
import { Link, useNavigate } from 'react-router-dom';

import Note from './Note';
import CouponsInfo from './CouponsInfo';
import EventInformation from './EventInformation';
import ContactInformation from './ContactInformation';
import BookingInformation from './BookingInformation';
import PaymentInformation from './PaymentInformation';
import SpecialRequirement from './SpecialRequirement';
import LegacyNotes from './LegacyNotes';

import FileIcon from '../../Assets/Img/file.svg';
import EmailIcon from '../../Assets/Img/email.svg';
import { useSelector } from 'react-redux';
import {
  getHistoryPlace,
  updatePlaceBy,
} from 'store/reducers/Booking/changePlace.slice';
import ChangePlace from './ChangePlace';

export default function Reactive({
  pages,
  enquirieDetail,
  activeContactSourcesList,
  dispatch,
  id,
}) {
  const { historyList, isPlaceHistoryUpdate, historyPlaceLoading } =
    useSelector(({ changePlace }) => changePlace);

  const [open, setOpen] = useState(false);
  const [increasePlacesBy, setIncreasePlacesBy] = useState('');
  const [decreasePlacesBy, setDecreasePlacesBy] = useState('');
  const [incTotal, setIncTotal] = useState('');
  const [decrTotal, setDecrTotal] = useState('');

  const [increasePlacesError, setIncreasePlacesError] = useState('');
  const [decreasePlacesError, setDecreasePlacesError] = useState('');

  // const [correct, setCorrect] = useState(true);

  const handleClickOpen = () => {
    setOpen(true);
    dispatch(getHistoryPlace(id));
  };
  const handleClose = () => {
    setOpen(false);
    setIncreasePlacesError('');
    setDecreasePlacesError('');
    setIncreasePlacesBy('');
    setDecreasePlacesBy('');
    // setCorrect(true);
  };

  const handleIncreasePlace = () => {
    if (increasePlacesBy === '') {
      setIncreasePlacesError('Please enter increase place');
    } else {
      setIncreasePlacesError('');
      dispatch(
        updatePlaceBy({
          booking_id: id,
          values: {
            places_change_by: Number(increasePlacesBy),
            is_inc: true,
          },
        }),
      );
    }
  };

  const handleDecreasePlace = () => {
    if (decreasePlacesBy === '') {
      setDecreasePlacesError('Please enter decrease place');
    } else if (
      decreasePlacesBy >
      enquirieDetail?.booking_info?.confirmed_places +
        enquirieDetail?.booking_info?.provisional_places
    ) {
      setDecreasePlacesError('Not enough places booked');
    } else {
      setDecreasePlacesError('');
      dispatch(
        updatePlaceBy({
          booking_id: id,
          values: {
            places_change_by: Number(decreasePlacesBy),
            is_inc: false,
          },
        }),
      );
    }
  };
  useEffect(() => {
    if (isPlaceHistoryUpdate) {
      dispatch(getHistoryPlace(id));
      setOpen(false);
      setIncreasePlacesBy('');
      setDecreasePlacesBy('');
    }
  }, [isPlaceHistoryUpdate]);
  const navigate = useNavigate();

  return (
    <>
      <div className="edit_booking_content_wrap">
        <Row>
          <Col lg={6}>
            <div
              className="booking_head d-flex align-items-center justify-content-between mb-1 p-2"
              style={{
                backgroundColor: pages === 'enquiries' ? '#6666cc' : '',
              }}
            >
              <h4 className="text_light m-0">
                {pages === 'enquiries' ? 'Enquiry: ' : 'Booking: '}
                <span
                  style={{
                    color: pages === 'enquiries' ? '#fff' : '',
                  }}
                >
                  {enquirieDetail?.ref_number}
                </span>{' '}
                - ({enquirieDetail?.booking_unique_id}{' '}
                {enquirieDetail?.ref_number}){' '}
                {pages === 'enquiries' &&
                  `- Sec Code: ${enquirieDetail?.booking_uid}`}
              </h4>
              <h4
                className="fw_600 m-0"
                style={{
                  color: pages === 'enquiries' ? '#fff' : '',
                }}
              >
                {enquirieDetail?.created_at
                  ? moment(enquirieDetail?.created_at).format('YYYY')
                  : ''}
              </h4>
            </div>
            <div className="booking_contact_info">
              <ContactInformation
                pages={pages}
                enquirieDetail={enquirieDetail}
                activeContactSourcesList={activeContactSourcesList}
                id={id}
              />
            </div>
          </Col>
          <Col lg={6}>
            <div className="d-flex flex-wrap">
              <div className="booking_left_head">
                <ul>
                  {pages === 'booking' && (
                    <>
                      {((enquirieDetail?.booking_info?.confirmed_places > 0 &&
                        !enquirieDetail?.booking_info?.provisional_places) ||
                        enquirieDetail?.is_invoice ||
                        enquirieDetail?.is_cancelled) && (
                        <li>
                          <Link
                            to={`/edit-bookings/invoices/${enquirieDetail?._id}`}
                            className="btn_border small me-2"
                          >
                            Invoicing
                          </Link>
                        </li>
                      )}
                      {((enquirieDetail?.booking_info?.confirmed_places > 0 &&
                        !enquirieDetail?.booking_info?.provisional_places) ||
                        enquirieDetail?.is_invoice) && (
                        <li>
                          <Link
                            to={`/edit-bookings/booking-billable-items/${enquirieDetail?._id}`}
                            className="btn_border small"
                          >
                            Billable Items
                          </Link>
                        </li>
                      )}
                    </>
                  )}
                </ul>
              </div>
              <div className="booking_right_head ms-auto">
                <ul>
                  {pages === 'booking' && (
                    <>
                      {enquirieDetail?.is_booking && (
                        <>
                          <li>
                            <Link
                              to={`${process.env.REACT_APP_WEBSITE_URL}login?email=${enquirieDetail?.contact?.email_primary}&password=frmcrmbo`}
                              className="btn_border small"
                              target="_blank"
                            >
                              Log into BPE.com
                            </Link>
                          </li>
                          <li>
                            <Link
                              className="btn_border small"
                              onClick={handleClickOpen}
                            >
                              Change Places
                            </Link>
                          </li>
                          <li>
                            <Link
                              to={`/add-payment/${enquirieDetail?._id}`}
                              className="btn_border small"
                            >
                              Payments
                            </Link>
                          </li>
                        </>
                      )}
                    </>
                  )}
                  <li>
                    <button
                      className="btn_icon"
                      onClick={() => {
                        if (pages === 'booking') {
                          navigate(
                            `/send-new-email/${enquirieDetail?._id}?${pages}=true&booking_confirmation=web_booking_confirmation`,
                            {
                              state: { enq_id: `${enquirieDetail?._id}` },
                            },
                          );
                        } else {
                          navigate(
                            `/send-new-email/${enquirieDetail?._id}?${pages}=true&default=default`,
                            {
                              state: { enq_id: `${enquirieDetail?._id}` },
                            },
                          );
                        }
                      }}
                    >
                      <img src={EmailIcon} alt="Email Icon" />
                    </button>
                  </li>
                  <li>
                    <Link
                      className="btn_icon"
                      to={`/send-new-letter/${enquirieDetail?._id}?${pages}=true&contactid=${enquirieDetail?.contact?._id}`}
                    >
                      <img src={FileIcon} alt="File Icon" />
                    </Link>
                  </li>
                </ul>
              </div>
            </div>
            <EventInformation pages={pages} enquirieDetail={enquirieDetail} />
            <BookingInformation pages={pages} enquirieDetail={enquirieDetail} />
            {pages === 'booking' && (
              <CouponsInfo enquirieDetail={enquirieDetail} id={id} />
            )}
            <PaymentInformation
              pages={pages}
              enquirieDetail={enquirieDetail}
              id={id}
            />
          </Col>
          <Col xs={12}>
            {pages === 'booking' && (
              <SpecialRequirement
                pages={pages}
                enquirieDetail={enquirieDetail}
              />
            )}
            <Note id={id} enquirieDetail={enquirieDetail} />
          </Col>
          <Col xs={12}>
            <LegacyNotes
              enquirieDetail={enquirieDetail}
              pages={pages}
              id={id}
            />
          </Col>
        </Row>
      </div>
      <ChangePlace
        enquirieDetail={enquirieDetail}
        open={open}
        handleClose={handleClose}
        historyPlaceLoading={historyPlaceLoading}
        historyList={historyList}
        increasePlacesBy={increasePlacesBy}
        increasePlacesError={increasePlacesError}
        incTotal={incTotal}
        setIncreasePlacesBy={setIncreasePlacesBy}
        setIncreasePlacesError={setIncreasePlacesError}
        setIncTotal={setIncTotal}
        decreasePlacesBy={decreasePlacesBy}
        decreasePlacesError={decreasePlacesError}
        decrTotal={decrTotal}
        setDecreasePlacesBy={setDecreasePlacesBy}
        setDecreasePlacesError={setDecreasePlacesError}
        setDecrTotal={setDecrTotal}
        handleIncreasePlace={handleIncreasePlace}
        handleDecreasePlace={handleDecreasePlace}
        // setCorrect={setCorrect}
        // correct={correct}
        place="title"
      />
    </>
  );
}
