import React from 'react';
import PropTypes from 'prop-types';
import { Button, Col, Row } from 'react-bootstrap';
import {
  FormGroup,
  TextField,
  FormControl,
  Dialog,
  DialogTitle,
  DialogContent,
  IconButton,
  Tooltip,
  styled,
} from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';
import Loader from 'Components/Common/Loader';
import moment from 'moment';
import PlusIcon from '../../Assets/Img/plus.svg';
import MinusIcon from '../../Assets/Img/minus.svg';
import InfoIcon from '../../Assets/Img/info-icon.svg';
import CrossIcon from '../../Assets/Img/cross-red.svg';
import { contactTypes } from 'utils/FieldValues';
import { addTax, numberRegex, toMoney } from 'utils/common';
import { useSelector } from 'react-redux';

const BootstrapDialog = styled(Dialog)(({ theme }) => ({
  '& .MuiDialogContent-root': {
    padding: theme.spacing(2),
  },
  '& .MuiDialogActions-root': {
    padding: theme.spacing(1),
  },
}));

function BootstrapDialogTitle(props) {
  const { children, onClose, ...other } = props;

  return (
    <DialogTitle sx={{ m: 0, p: 2 }} {...other}>
      {children}
      {onClose ? (
        <IconButton
          aria-label="close"
          onClick={onClose}
          sx={{
            position: 'absolute',
            right: 19,
            top: 19,
            color: theme => theme.palette.grey[600],
          }}
        >
          <CloseIcon />
        </IconButton>
      ) : null}
    </DialogTitle>
  );
}

BootstrapDialogTitle.propTypes = {
  children: PropTypes.node,
  onClose: PropTypes.func.isRequired,
};

export default function ChangePlace({
  enquirieDetail,
  open,
  handleClose,
  historyPlaceLoading,
  historyList,
  increasePlacesBy,
  increasePlacesError,
  incTotal,
  setIncreasePlacesBy,
  setIncreasePlacesError,
  setIncTotal,
  decreasePlacesBy,
  decreasePlacesError,
  decrTotal,
  setDecreasePlacesBy,
  setDecreasePlacesError,
  setDecrTotal,
  handleIncreasePlace,
  handleDecreasePlace,
  place,
  // correct,
  // setCorrect,
}) {
  const { userPermissionDetail } = useSelector(({ user }) => user);
  const increasePlace = () => {
    if (
      (userPermissionDetail?.admin || userPermissionDetail?.super) &&
      userPermissionDetail?.changeplaces
    ) {
      handleIncreasePlace();
    } else return;
  };
  const decreasePlace = () => {
    if (
      (userPermissionDetail?.admin || userPermissionDetail?.super) &&
      userPermissionDetail?.changeplaces
    ) {
      handleDecreasePlace();
    } else return;
  };

  return (
    <BootstrapDialog
      aria-labelledby="customized-dialog2-title"
      open={open}
      className="medium_popup"
    >
      {historyPlaceLoading && <Loader />}
      <BootstrapDialogTitle id="customized-dialog2-title" onClose={handleClose}>
        {place === 'title' && 'Change Places'}
        {place === 'max' && 'Change Maximum Places Booked'}
      </BootstrapDialogTitle>
      <DialogContent dividers>
        <div className="popup_content_wrap">
          <Row>
            <Col xs={7}>
              {place === 'title' && (
                <div className="popup_content_inner">
                  <ul>
                    <li>
                      <label>Contact Name:</label>
                      <div className="right_content">
                        <p className="m-0">
                          {enquirieDetail?.contact?.title +
                            ` ` +
                            enquirieDetail?.contact?.first_name +
                            ` ` +
                            enquirieDetail?.contact?.surname +
                            ` `}
                        </p>
                      </div>
                    </li>
                    <li>
                      <label>Contact Account:</label>
                      <div className="right_content">
                        <p className="m-0">
                          {enquirieDetail?.contact?.account?.type
                            ? contactTypes[
                                enquirieDetail?.contact?.account?.type
                              ]?.name
                            : '-'}
                        </p>
                      </div>
                    </li>
                    <li>
                      <label>Event:</label>
                      <div className="right_content">
                        <p className="m-0">
                          {enquirieDetail?.event_info?.internal_name}
                        </p>
                      </div>
                    </li>
                    <li>
                      <label>Event Date:</label>
                      <div className="right_content">
                        <p className="m-0">
                          {moment(
                            enquirieDetail?.event_info?.event_date?.date,
                          ).format('ddd Do MMM YYYY')}
                        </p>
                      </div>
                    </li>
                    <li>
                      <label>Provisional Places:</label>
                      <div className="right_content">
                        <p className="m-0">
                          {enquirieDetail?.booking_info?.provisional_places}
                        </p>
                      </div>
                    </li>
                    <li>
                      <label>Confirmed Places:</label>
                      <div className="right_content">
                        <p className="m-0">
                          {enquirieDetail?.booking_info?.confirmed_places}
                        </p>
                      </div>
                    </li>
                    <li>
                      <label>Available Places:</label>
                      <div className="right_content">
                        <p className="m-0">
                          {enquirieDetail?.booking_info?.places}
                          <span className="text_light">
                            {enquirieDetail?.booking_info?.overbook_maximum
                              ? '(' +
                                enquirieDetail?.booking_info?.overbook_maximum +
                                ')'
                              : ''}
                          </span>
                        </p>
                      </div>
                    </li>
                    <li>
                      <label>Tickets Price:</label>
                      <div className="right_content">
                        <p className="m-0">
                          £{toMoney(enquirieDetail?.event_info?.ticket_price)}
                          <span className="text_light">
                            {' '}
                            / £
                            {toMoney(
                              addTax(
                                enquirieDetail?.event_info?.ticket_price,
                                enquirieDetail?.event_info?.tax_code
                                  ?.percentage,
                              ),
                            )}
                          </span>
                        </p>
                      </div>
                    </li>
                  </ul>
                </div>
              )}
              {place === 'max' && (
                <div className="popup_content_inner h-100">
                  <div className="bg_gray_box p-3 h-100">
                    <p>
                      Administrators can change the maximum places count to
                      alter the retained deposits for each booking.
                    </p>
                    <p>
                      NOTE: If you have already got deposit payments or invoices
                      attached to this booking they NEED TO BE REVERSED and
                      re-entered AFTER you have changed the maximum places
                      value.
                    </p>
                    <p>
                      This change does not affect the current placed booked but
                      only the maximum amount of places ever booked that is
                      stored in the system.
                    </p>
                  </div>
                </div>
              )}
            </Col>
            <Col xs={5}>
              {enquirieDetail?.is_invoice ||
              ((userPermissionDetail?.admin || userPermissionDetail?.super) &&
                userPermissionDetail?.changeplaces) ? (
                <>
                  {/* {enquirieDetail?.is_invoice && correct ? (
                    <>
                      <p>
                        This booking has already been invoiced - changing places
                        now will create a credit note and re-invoice for the new
                        amount. Please only proceed if you have collected all
                        the relevant paperwork from the customer to authorise
                        the change to places.
                        <br />
                        <div className="card_footer admin_card_footer mb-2">
                          <Row className="justify-content-center mt-2">
                            <Col xs={8}>
                              <Button
                                type="button"
                                className="btn_border small"
                                onClick={() => setCorrect(false)}
                              >
                                I HAVE CORRECT DOCUMENTS
                              </Button>
                            </Col>
                          </Row>
                        </div>
                      </p>
                    </>
                  ) : ( */}
                  <div className="popup_content_inner">
                    <ul className="mb-3 changes_places">
                      <li className="pb-3 flex-wrap">
                        <label className="w-100">
                          Increase Places By:
                          <sup className="text_primary">*</sup>
                        </label>
                        <div className="right_content w-100">
                          <div className="d-flex align-items-center">
                            <FormGroup>
                              <FormControl fullWidth className="small_select">
                                <TextField
                                  id="Discount"
                                  type="number"
                                  onKeyDown={e => {
                                    numberRegex(e);
                                  }}
                                  variant="outlined"
                                  className="input_wrap"
                                  inputProps={{
                                    min: 0,
                                    step: 'any',
                                  }}
                                  disabled={
                                    (userPermissionDetail?.admin ||
                                      userPermissionDetail?.super) &&
                                    userPermissionDetail?.changeplaces
                                      ? false
                                      : true
                                  }
                                  value={increasePlacesBy}
                                  onChange={e => {
                                    if (e.target.value !== '') {
                                      setIncreasePlacesError('');
                                    }
                                    setIncreasePlacesBy(e.target.value);
                                    if (place === 'max') {
                                      setIncTotal(
                                        Number(e.target.value) +
                                          enquirieDetail?.max_places,
                                      );
                                    } else {
                                      setIncTotal(
                                        Number(e.target.value) +
                                          enquirieDetail?.booking_info
                                            ?.confirmed_places +
                                          enquirieDetail?.booking_info
                                            ?.provisional_places,
                                      );
                                    }
                                  }}
                                />
                                {increasePlacesError !== '' && (
                                  <span className="d-block text-danger text_small lookup_error">
                                    {increasePlacesError}
                                  </span>
                                )}
                              </FormControl>
                            </FormGroup>
                            {increasePlacesBy >
                            enquirieDetail?.booking_info?.overbook_maximum ? (
                              <Button className="btn_plus ms-2">
                                <img src={CrossIcon} alt="Cross Icon" />
                              </Button>
                            ) : (
                              <>
                                <Button
                                  className="btn_plus ms-2"
                                  onClick={increasePlace}
                                >
                                  <img src={PlusIcon} alt="Plus Icon" />
                                </Button>
                                <span className="ms-3">
                                  {increasePlacesBy !== ''
                                    ? ' To ' + incTotal
                                    : ''}
                                </span>
                              </>
                            )}
                          </div>
                        </div>
                      </li>
                      <li className="pb-3 flex-wrap">
                        <label className="w-100">
                          Decrease Places By:
                          <sup className="text_primary">*</sup>
                        </label>
                        <div className="right_content w-100">
                          <div className="d-flex">
                            <FormGroup>
                              <FormControl fullWidth className="small_select">
                                <TextField
                                  id="Discount"
                                  type="number"
                                  variant="outlined"
                                  className="input_wrap"
                                  onKeyDown={e => {
                                    numberRegex(e);
                                  }}
                                  inputProps={{
                                    min: 0,
                                    step: 'any',
                                  }}
                                  disabled={
                                    (userPermissionDetail?.admin ||
                                      userPermissionDetail?.super) &&
                                    userPermissionDetail?.changeplaces
                                      ? false
                                      : true
                                  }
                                  value={decreasePlacesBy}
                                  onChange={e => {
                                    if (e.target.value !== '') {
                                      setDecreasePlacesError('');
                                    }
                                    setDecreasePlacesBy(e.target.value);
                                    if (place === 'max') {
                                      setDecrTotal(
                                        Number(e.target.value) -
                                          enquirieDetail?.max_places,
                                      );
                                    } else {
                                      setDecrTotal(
                                        Number(e.target.value) -
                                          (enquirieDetail?.booking_info
                                            ?.confirmed_places +
                                            enquirieDetail?.booking_info
                                              ?.provisional_places),
                                      );
                                    }
                                  }}
                                />
                                {decreasePlacesError !== '' && (
                                  <span className="d-block text-danger text_small lookup_error">
                                    {decreasePlacesError}
                                  </span>
                                )}
                              </FormControl>
                            </FormGroup>
                            <Button
                              className="btn_plus ms-2"
                              onClick={decreasePlace}
                            >
                              <img src={MinusIcon} alt="Minus Icon" />
                            </Button>
                            <span className="ms-3">
                              {decreasePlacesBy !== ''
                                ? ' To ' + Math.abs(decrTotal)
                                : ''}
                              {/* {decreasePlacesBy !== ''
                                ? enquirieDetail?.booking_info
                                    ?.confirmed_places +
                                    enquirieDetail?.booking_info
                                      ?.provisional_places >
                                  decreasePlacesBy
                                  ? ' To ' + Math.abs(decrTotal)
                                  : 0
                                : ''} */}
                            </span>
                          </div>
                        </div>
                      </li>
                    </ul>
                    <div className="bg_gray_box history_wrapper p-3">
                      <label className="mb-2">History</label>
                      <ul>
                        {historyList?.map(item => {
                          return (
                            <li className="d-flex align-items-center justify-content-between mb-2">
                              <div className="d-flex align-items-center">
                                <Tooltip title={item?.note}>
                                  <img
                                    src={InfoIcon}
                                    alt="Info Icon"
                                    className="me-2"
                                  />
                                </Tooltip>
                                {/* {moment(item?.date).format(
                                  'DD/MM/YYYY HH:mm:ss',
                                )} */}
                                {item?.time}
                                <span style={{ color: '#de3957' }}>
                                  {item?.is_confirm === true ? '(CNF)' : ''}
                                </span>
                              </div>
                              <span>
                                {item?.confirm_places}{' '}
                                <span className="text_light">
                                  ({item?.change_places})
                                </span>
                              </span>
                            </li>
                          );
                        })}
                      </ul>
                    </div>
                  </div>
                  {/* )} */}
                </>
              ) : (
                <p className="text-center mt-4 mx-5">
                  This booking has already been invoiced - changing places now
                  will create a credit note and re-invoice for the new amount.
                  Places can only be changed by the customer online or by an
                  administrator once all the relevant paperwork has ben
                  collected.
                </p>
              )}
            </Col>
          </Row>
        </div>
      </DialogContent>
    </BootstrapDialog>
  );
}
