import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { FormControl, TextField } from '@mui/material';
import DialogContent from '@mui/material/DialogContent';
import Dialog from '@mui/material/Dialog';
import DialogTitle from '@mui/material/DialogTitle';
import IconButton from '@mui/material/IconButton';
import CloseIcon2 from '@mui/icons-material/Close';
import { Button } from 'react-bootstrap';
import { updateEnquiries } from 'store/reducers/Enquiry/enquiries.slice';
import { useDispatch } from 'react-redux';
import { numberRegexE } from 'utils/common';

function BootstrapDialogTitle(props) {
  const { children, onClose, ...other } = props;

  return (
    <DialogTitle sx={{ m: 0, p: 2 }} {...other}>
      {children}
      {onClose ? (
        <IconButton
          aria-label="close"
          onClick={onClose}
          sx={{
            position: 'absolute',
            right: 19,
            top: 19,
            color: color => color.palette.grey[600],
          }}
        >
          <CloseIcon2 />
        </IconButton>
      ) : null}
    </DialogTitle>
  );
}
export default function SpecialRequirement({ pages, enquirieDetail }) {
  const navigate = useNavigate();
  const dispatch = useDispatch();

  const [isEnable, setIsEnable] = useState(false);
  const [openPopUp, setOpenPopUp] = useState(false);
  const [contentText, setContentText] = useState('');
  const [requirementData, setRequirementData] = useState({
    dairy_free: '',
    gluten_free: '',
    halal: '',
    nut_allergy: '',
    vegan: '',
    vegetarian: '',
    wheelchair_user: '',
  });
  useEffect(() => {
    if (Object.keys(enquirieDetail).length > 0) {
      if (enquirieDetail?.special_requirements) {
        setRequirementData({
          dairy_free: enquirieDetail?.special_requirements?.dairy_free,
          gluten_free: enquirieDetail?.special_requirements?.gluten_free,
          halal: enquirieDetail?.special_requirements?.halal,
          nut_allergy: enquirieDetail?.special_requirements?.nut_allergy,
          vegan: enquirieDetail?.special_requirements?.vegan,
          vegetarian: enquirieDetail?.special_requirements?.vegetarian,
          wheelchair_user:
            enquirieDetail?.special_requirements?.wheelchair_user,
        });
      }
    }
  }, [enquirieDetail]);
  const OpenDialoguePopUp = item => {
    setContentText(item);
    setOpenPopUp(true);
  };
  const ClosePopUp = () => {
    setOpenPopUp(false);
  };
  const HandleChange = () => {
    setIsEnable(!isEnable);
    dispatch(
      updateEnquiries({
        _id: enquirieDetail?._id,
        is_guest_system: !enquirieDetail?.is_guest_system,
      }),
    );
    setOpenPopUp(false);
  };
  return (
    <>
      <div className="special_requirement">
        <div className="card_wrapper mb-4">
          <div className="card_header d-flex align-items-center justify-content-between py-2 px-3">
            <h4 className="m-0 py-1 text_white">Special Requirements</h4>
          </div>
          <div className="card_body">
            <ul>
              <li className="align-items-center">
                <label className="fw_500">Special Requirements:</label>
                <div className="right_content">
                  {enquirieDetail?.is_guest_system === true && (
                    <p>
                      This booking uses the Guest List system - please{' '}
                      <span
                        className="text_decoration"
                        onClick={() => {
                          navigate(
                            `/edit-bookings/guest-list/${enquirieDetail?._id}`,
                            {
                              state: {
                                confirmed_places:
                                  enquirieDetail?.booking_info
                                    ?.confirmed_places,
                                provisional_places:
                                  enquirieDetail?.booking_info
                                    ?.provisional_places,
                              },
                            },
                          );
                        }}
                      >
                        click here to update guests
                      </span>
                    </p>
                  )}

                  {enquirieDetail?.is_guest_system === false && (
                    <>
                      <div className="d-flex align-items-center mb-3">
                        <p className="m-0">
                          Please enter total numbers against each requirements
                          type - other values will be converted to 0
                        </p>
                        <Button
                          className="btn_border small mx-2"
                          onClick={() => {
                            dispatch(
                              updateEnquiries({
                                _id: enquirieDetail?._id,
                                special_requirements: requirementData,
                              }),
                            );
                          }}
                        >
                          Update
                        </Button>
                      </div>
                      <div className="special_requirment_list_wrap">
                        <ul>
                          <li>
                            <div className="d-flex align-items-center">
                              <FormControl>
                                <TextField
                                  id="Dairyfree"
                                  type="number"
                                  variant="outlined"
                                  className="custom-input"
                                  name="dairy_free"
                                  onKeyDown={e => {
                                    numberRegexE(e);
                                  }}
                                  inputProps={{ min: 0, step: 'any' }}
                                  value={requirementData.dairy_free}
                                  onChange={e => {
                                    setRequirementData({
                                      ...requirementData,
                                      dairy_free: parseInt(e.target.value),
                                    });
                                  }}
                                  onFocus={() => {
                                    if (requirementData.dairy_free == '0') {
                                      setRequirementData({
                                        ...requirementData,
                                        dairy_free: parseInt(''),
                                      });
                                    }
                                  }}
                                />
                              </FormControl>
                              <span className="ms-1">Dairy Free</span>
                            </div>
                          </li>
                          <li>
                            <div className="d-flex align-items-center">
                              <FormControl>
                                <TextField
                                  id="Glutenfree"
                                  type="number"
                                  variant="outlined"
                                  className="custom-input"
                                  name="gluten_free"
                                  onKeyDown={e => {
                                    numberRegexE(e);
                                  }}
                                  inputProps={{ min: 0, step: 'any' }}
                                  value={requirementData.gluten_free}
                                  onChange={e => {
                                    setRequirementData({
                                      ...requirementData,
                                      gluten_free: parseInt(e.target.value),
                                    });
                                  }}
                                  onFocus={() => {
                                    if (requirementData.gluten_free == '0') {
                                      setRequirementData({
                                        ...requirementData,
                                        gluten_free: parseInt(''),
                                      });
                                    }
                                  }}
                                />
                              </FormControl>
                              <span className="ms-1">Gluten Free</span>
                            </div>
                          </li>
                          <li>
                            <div className="d-flex align-items-center">
                              <FormControl>
                                <TextField
                                  id="Halal"
                                  type="number"
                                  variant="outlined"
                                  className="custom-input"
                                  name="halal"
                                  onKeyDown={e => {
                                    numberRegexE(e);
                                  }}
                                  inputProps={{ min: 0, step: 'any' }}
                                  value={requirementData.halal}
                                  onChange={e => {
                                    setRequirementData({
                                      ...requirementData,
                                      halal: parseInt(e.target.value),
                                    });
                                  }}
                                  onFocus={() => {
                                    if (requirementData.halal == '0') {
                                      setRequirementData({
                                        ...requirementData,
                                        halal: parseInt(''),
                                      });
                                    }
                                  }}
                                />
                              </FormControl>
                              <span className="ms-1">Halal</span>
                            </div>
                          </li>
                          <li>
                            <div className="d-flex align-items-center">
                              <FormControl>
                                <TextField
                                  id="NutAllergy"
                                  type="number"
                                  variant="outlined"
                                  className="custom-input"
                                  name="nut_allergy"
                                  onKeyDown={e => {
                                    numberRegexE(e);
                                  }}
                                  inputProps={{ min: 0, step: 'any' }}
                                  value={requirementData.nut_allergy}
                                  onChange={e => {
                                    setRequirementData({
                                      ...requirementData,
                                      nut_allergy: parseInt(e.target.value),
                                    });
                                  }}
                                  onFocus={() => {
                                    if (requirementData.nut_allergy == '0') {
                                      setRequirementData({
                                        ...requirementData,
                                        nut_allergy: parseInt(''),
                                      });
                                    }
                                  }}
                                />
                              </FormControl>
                              <span className="ms-1">Nut Allergy</span>
                            </div>
                          </li>
                          <li>
                            <div className="d-flex align-items-center">
                              <FormControl>
                                <TextField
                                  id="Vegan"
                                  type="number"
                                  variant="outlined"
                                  className="custom-input"
                                  name="vegan"
                                  onKeyDown={e => {
                                    numberRegexE(e);
                                  }}
                                  inputProps={{ min: 0, step: 'any' }}
                                  value={requirementData.vegan}
                                  onChange={e => {
                                    setRequirementData({
                                      ...requirementData,
                                      vegan: parseInt(e.target.value),
                                    });
                                  }}
                                  onFocus={() => {
                                    if (requirementData.vegan == '0') {
                                      setRequirementData({
                                        ...requirementData,
                                        vegan: parseInt(''),
                                      });
                                    }
                                  }}
                                />
                              </FormControl>
                              <span className="ms-1">Vegan</span>
                            </div>
                          </li>
                          <li>
                            <div className="d-flex align-items-center">
                              <FormControl>
                                <TextField
                                  id="Vegetarian"
                                  type="number"
                                  variant="outlined"
                                  className="custom-input"
                                  name="vegetarian"
                                  onKeyDown={e => {
                                    numberRegexE(e);
                                  }}
                                  inputProps={{ min: 0, step: 'any' }}
                                  value={requirementData.vegetarian}
                                  onChange={e => {
                                    setRequirementData({
                                      ...requirementData,
                                      vegetarian: parseInt(e.target.value),
                                    });
                                  }}
                                  onFocus={() => {
                                    if (requirementData.vegetarian == '0') {
                                      setRequirementData({
                                        ...requirementData,
                                        vegetarian: parseInt(''),
                                      });
                                    }
                                  }}
                                />
                              </FormControl>
                              <span className="ms-1">Vegetarian</span>
                            </div>
                          </li>
                          <li>
                            <div className="d-flex align-items-center">
                              <FormControl>
                                <TextField
                                  id="Wheelchair"
                                  type="number"
                                  variant="outlined"
                                  className="custom-input"
                                  name="wheelchair_user"
                                  onKeyDown={e => {
                                    numberRegexE(e);
                                  }}
                                  inputProps={{ min: 0, step: 'any' }}
                                  value={requirementData.wheelchair_user}
                                  onChange={e => {
                                    setRequirementData({
                                      ...requirementData,
                                      wheelchair_user: parseInt(e.target.value),
                                    });
                                  }}
                                  onFocus={() => {
                                    if (
                                      requirementData.wheelchair_user == '0'
                                    ) {
                                      setRequirementData({
                                        ...requirementData,
                                        wheelchair_user: parseInt(''),
                                      });
                                    }
                                  }}
                                />
                              </FormControl>
                              <span className="ms-1">Wheelchair User</span>
                            </div>
                          </li>
                        </ul>
                      </div>
                    </>
                  )}
                  {enquirieDetail?.is_guest_system === true && (
                    <p className="m-0">
                      This booking currently has{' '}
                      <span className="text_primary">
                        {enquirieDetail?.total_guests}
                      </span>{' '}
                      guests added - to disable the guest list for this booking
                      <span
                        to=""
                        className="text_decoration ms-1"
                        onClick={() => {
                          OpenDialoguePopUp('disable');
                        }}
                      >
                        click here
                      </span>
                    </p>
                  )}
                  {enquirieDetail?.is_guest_system === false && (
                    <p>
                      This booking currently has the guest system disabled - to
                      re-enable the guest list for this booking
                      <span
                        to=""
                        className="text_decoration ms-1"
                        onClick={() => {
                          OpenDialoguePopUp();
                        }}
                      >
                        click here
                      </span>
                    </p>
                  )}
                </div>
              </li>
            </ul>
          </div>
        </div>
      </div>

      <Dialog
        aria-labelledby="CancelBooking-title"
        open={openPopUp}
        className="delete_popup"
      >
        <BootstrapDialogTitle
          id="CancelBooking-title"
          onClose={ClosePopUp}
        ></BootstrapDialogTitle>
        <DialogContent dividers>
          <div className="popup_content_wrap">
            <div className="delete_popup_wrap">
              <h2 className="mb-3">
                {contentText == 'disable' ? 'Disable' : 'Enable'} Guest System
              </h2>
              <p>
                Are you sure you want to{' '}
                {contentText == 'disable' ? 'disable' : 'enable'} the guest
                system?
              </p>
              <ul className="d-flex align-items-center justify-content-center">
                <li>
                  <Button className="btn_border mx-2" onClick={ClosePopUp}>
                    Cancel
                  </Button>
                </li>
                <li>
                  <Button
                    className="btn_primary mx-2"
                    onClick={() => {
                      HandleChange();
                    }}
                  >
                    Ok
                  </Button>
                </li>
              </ul>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}
