import { useEffect, useState } from 'react';
import { Button } from 'react-bootstrap';
import { FormGroup, TextField, FormControl } from '@mui/material';

import {
  getEnquiriesData,
  updateEnquiries,
} from 'store/reducers/Enquiry/enquiries.slice';
import { useDispatch, useSelector } from 'react-redux';
import {
  getHistoryPlace,
  updatePlaceBy,
} from 'store/reducers/Booking/changePlace.slice';
import ChangePlace from './ChangePlace';
import {
  addTax,
  applyDiscount,
  formatNumberWithCommas,
  numberRegexE,
  toMoney,
  zeroRoundTo,
} from 'utils/common';

export default function PaymentInformation({ pages, enquirieDetail, id }) {
  const dispatch = useDispatch();

  const { historyList, isPlaceHistoryUpdate, historyPlaceLoading } =
    useSelector(({ changePlace }) => changePlace);
  const { userPermissionDetail } = useSelector(({ user }) => user);

  const [open, setOpen] = useState(false);
  const [discountUpdate, setDiscountUpdate] = useState(false);
  const [discount, setDiscount] = useState('');

  const [increasePlacesBy, setIncreasePlacesBy] = useState('');
  const [decreasePlacesBy, setDecreasePlacesBy] = useState('');
  const [incTotal, setIncTotal] = useState('');
  const [decrTotal, setDecrTotal] = useState('');

  const [increasePlacesError, setIncreasePlacesError] = useState('');
  const [decreasePlacesError, setDecreasePlacesError] = useState('');

  // const [correct, setCorrect] = useState(true);

  useEffect(() => {
    if (enquirieDetail) {
      setDiscount(enquirieDetail?.payment_info?.discount?.toFixed(2));
    }
  }, [enquirieDetail]);

  const handleClickOpen = () => {
    setOpen(true);
    dispatch(getHistoryPlace(id));
  };
  const handleClose = () => {
    setOpen(false);
    setIncreasePlacesError('');
    setDecreasePlacesError('');
    setIncreasePlacesBy('');
    setDecreasePlacesBy('');
    // setCorrect(true);
  };

  const handleIncreasePlace = () => {
    if (increasePlacesBy === '') {
      setIncreasePlacesError('Please enter increase place');
    } else {
      setIncreasePlacesError('');
      dispatch(
        updatePlaceBy({
          booking_id: id,
          values: {
            places_change_by: Number(increasePlacesBy),
            is_max_places_change: true,
          },
        }),
      );
    }
  };

  const handleDecreasePlace = () => {
    if (decreasePlacesBy === '') {
      setDecreasePlacesError('Please enter decrease place');
    } else if (decreasePlacesBy > enquirieDetail?.max_places) {
      setDecreasePlacesError('Not enough places booked');
    } else {
      setDecreasePlacesError('');
      dispatch(
        updatePlaceBy({
          booking_id: id,
          values: {
            places_change_by: Number(decreasePlacesBy),
            is_max_places_change: false,
          },
        }),
      );
    }
  };
  useEffect(() => {
    if (isPlaceHistoryUpdate) {
      dispatch(getHistoryPlace(id));
      dispatch(getEnquiriesData(id));
      setOpen(false);
      setIncreasePlacesBy('');
      setDecreasePlacesBy('');
    }
  }, [isPlaceHistoryUpdate]);

  return (
    <>
      <div className="card_wrapper mb-4">
        <div
          className={`card_header d-flex align-items-center justify-content-between py-2 px-3 ${
            pages === 'enquiries' ? 'enquiry' : ''
          }`}
        >
          <h4 className="m-0 py-1 text_white">Payment Information</h4>
        </div>
        <div className="card_body">
          <ul>
            <li>
              <label className="fw_500">Discount:</label>
              <div className="right_content">
                <div className="d-flex justify-content-between align-items-center">
                  <div className="d-flex align-items-center">
                    <FormGroup className="input_wrap w-60">
                      <FormControl fullWidth className="small_select">
                        <TextField
                          id="Discount"
                          type="number"
                          variant="outlined"
                          className="input_wrap"
                          placeholder="Enter discount"
                          onKeyDown={e => {
                            numberRegexE(e);
                          }}
                          inputProps={{ min: 0, step: 'any' }}
                          value={discount}
                          onChange={e => {
                            setDiscount(e.target.value);
                          }}
                          onFocus={() => {
                            if (discount == '0.00') {
                              setDiscount('');
                            }
                          }}
                          // changes as per click up requirement
                          // onBlur={() => {
                          //   if (discount === '') {
                          //     setDiscount('0');
                          //   }
                          // }}
                        />
                      </FormControl>
                    </FormGroup>
                    {discount > 0 && <span className="ms-2">%</span>}
                  </div>
                  <Button
                    className="btn_border small"
                    onClick={() => {
                      dispatch(
                        updateEnquiries({
                          _id: enquirieDetail?._id,
                          discount: discount,
                        }),
                      );
                      setDiscountUpdate(true);
                    }}
                  >
                    {discountUpdate ? 'Updated' : 'Update Discount'}
                  </Button>
                </div>
              </div>
            </li>
            <li>
              <label className="fw_500">Ticket price (inc discount):</label>
              {enquirieDetail?.payment_info?.discount ? (
                <div className="right_content">
                  <p className="m-0">
                    £
                    {formatNumberWithCommas(
                      toMoney(
                        applyDiscount(
                          enquirieDetail?.event_info?.ticket_price,
                          enquirieDetail?.payment_info?.discount,
                        )?.toFixed(2),
                      ),
                    )}
                    <span className="text_light">
                      {' '}
                      / £
                      {formatNumberWithCommas(
                        toMoney(
                          addTax(
                            applyDiscount(
                              enquirieDetail?.event_info?.ticket_price,
                              enquirieDetail?.payment_info?.discount,
                            ),
                            enquirieDetail?.event_info?.tax_code?.percentage,
                          ),
                        ),
                      )}{' '}
                      @{' '}
                      {enquirieDetail?.event_info?.tax_code?.percentage
                        ? enquirieDetail?.event_info?.tax_code?.percentage %
                            1 ===
                          0
                          ? enquirieDetail?.event_info?.tax_code?.percentage
                          : enquirieDetail?.event_info?.tax_code?.percentage?.toFixed(
                              2,
                            )
                        : ''}
                      {'% '}
                      {enquirieDetail?.event_info?.tax_code?.public_name}
                    </span>
                  </p>
                </div>
              ) : (
                <div className="right_content">
                  <p className="m-0">
                    £
                    {formatNumberWithCommas(
                      toMoney(enquirieDetail?.event_info?.ticket_price),
                    )}
                    <span className="text_light">
                      {' '}
                      / £
                      {formatNumberWithCommas(
                        toMoney(
                          addTax(
                            enquirieDetail?.event_info?.ticket_price,
                            enquirieDetail?.event_info?.tax_code?.percentage,
                          ),
                        ),
                      )}{' '}
                      @{' '}
                      {enquirieDetail?.event_info?.tax_code?.percentage
                        ? enquirieDetail?.event_info?.tax_code?.percentage %
                            1 ===
                          0
                          ? enquirieDetail?.event_info?.tax_code?.percentage
                          : enquirieDetail?.event_info?.tax_code?.percentage?.toFixed(
                              2,
                            )
                        : ''}
                      {'% '}
                      {enquirieDetail?.event_info?.tax_code?.public_name}
                    </span>
                  </p>
                </div>
              )}
            </li>
            {pages === 'booking' && (
              <>
                <li>
                  <label className="fw_500">Billable Items:</label>
                  <div className="right_content">
                    <p className="m-0">
                      £
                      {formatNumberWithCommas(
                        enquirieDetail?.payment_info?.billable_items_amount?.toFixed(
                          2,
                        ),
                      )}
                    </p>
                  </div>
                </li>
                <li>
                  <label className="fw_500">Balance Due:</label>
                  <div className="right_content">
                    <div className="d-flex align-items-center justify-content-between">
                      <p className="m-0">
                        £
                        {formatNumberWithCommas(
                          enquirieDetail?.payment_info?.balance_due?.toFixed(2),
                        )}
                      </p>
                      {/* <Button className="btn_border small">
                        View Statement
                      </Button> */}
                    </div>
                  </div>
                </li>
                <li>
                  <label className="fw_500">Amount Paid:</label>
                  <div className="right_content">
                    <p className="m-0">
                      £
                      {formatNumberWithCommas(
                        zeroRoundTo(enquirieDetail?.payment_info?.amount_paid),
                      )}
                    </p>
                  </div>
                </li>
                <li>
                  <label className="fw_500">Deposits Received:</label>
                  <div className="right_content">
                    <p className="m-0 d-flex justify-content-between">
                      £
                      {formatNumberWithCommas(
                        enquirieDetail?.payment_info?.deposits_received?.toFixed(
                          2,
                        ),
                      )}
                      <span
                        className={
                          enquirieDetail?.max_places === 0
                            ? `text_decoration`
                            : `text_decoration cursor-pointer`
                        }
                        onClick={
                          userPermissionDetail?.super === true &&
                          enquirieDetail?.max_places > 0
                            ? handleClickOpen
                            : null
                        }
                      >
                        Max:{' '}
                        {enquirieDetail?.max_places
                          ? enquirieDetail?.max_places
                          : '0'}
                      </span>
                    </p>
                  </div>
                </li>
                <li>
                  <label className="fw_500">Deposits Retained:</label>
                  <div className="right_content">
                    <p className="m-0">
                      £
                      {formatNumberWithCommas(
                        enquirieDetail?.payment_info?.deposits_retained?.toFixed(
                          2,
                        ),
                      )}
                    </p>
                  </div>
                </li>
              </>
            )}
          </ul>
        </div>
      </div>
      <ChangePlace
        enquirieDetail={enquirieDetail}
        open={open}
        handleClose={handleClose}
        historyPlaceLoading={historyPlaceLoading}
        historyList={historyList}
        increasePlacesBy={increasePlacesBy}
        increasePlacesError={increasePlacesError}
        incTotal={incTotal}
        setIncreasePlacesBy={setIncreasePlacesBy}
        setIncreasePlacesError={setIncreasePlacesError}
        setIncTotal={setIncTotal}
        decreasePlacesBy={decreasePlacesBy}
        decreasePlacesError={decreasePlacesError}
        decrTotal={decrTotal}
        setDecreasePlacesBy={setDecreasePlacesBy}
        setDecreasePlacesError={setDecreasePlacesError}
        setDecrTotal={setDecrTotal}
        handleIncreasePlace={handleIncreasePlace}
        handleDecreasePlace={handleDecreasePlace}
        // setCorrect={setCorrect}
        // correct={correct}
        place="max"
      />
    </>
  );
}
