import React from 'react';
import PreviousSentEmails from './PreviousSentEmails';

const LegacyNotes = ({ enquirieDetail, pages, id }) => {
  return (
    <div>
      <div className="legacy_notes_wrap mb-3">
        <div className="card_wrapper">
          <div className="card_header d-flex align-items-center justify-content-between py-2 px-3">
            <h4 className="m-0 py-1 text_white">Legacy Notes</h4>
          </div>
          <div className="card_body">
            <div className="legacy_notes_btn_wrap text-end">
              <button type="button" className="btn_primary small">
                Clear Legacy Notes
              </button>
            </div>
            <ul className="my-2">
              {enquirieDetail?.legacy_notes?.account_internal_notes ? (
                <li>
                  <label className="fw_500">Notes on Account (internal):</label>
                  <div className="right_content">
                    <h5 className="m-0 fw_bold">
                      {enquirieDetail?.legacy_notes?.account_internal_notes}
                    </h5>
                  </div>
                </li>
              ) : (
                ''
              )}
              {enquirieDetail?.legacy_notes?.account_public_notes ? (
                <li>
                  <label className="fw_500">Notes on Account (public):</label>
                  <div className="right_content">
                    <h5 className="m-0 fw_bold">
                      {enquirieDetail?.legacy_notes?.account_public_notes}
                    </h5>
                  </div>
                </li>
              ) : (
                ''
              )}
              {enquirieDetail?.legacy_notes?.customer_notes ? (
                <li>
                  <label className="fw_500">Customer Notes:</label>
                  <div className="right_content">
                    <h5 className="m-0 fw_bold">
                      {enquirieDetail?.legacy_notes?.customer_notes}
                    </h5>
                  </div>
                </li>
              ) : (
                ''
              )}
            </ul>
            <div className="note_table_wrap p-2">
              {/* <div className="table_main_Wrapper p-2">
                {itemsInActive?.length ? (
                  <>
                    <div className="d-flex justify-content-between align-items-center mb-2">
                      <h5 className="text_primary m-0">Previous Sent Emails</h5>
                      <span>(Most Recent at the top)</span>
                    </div>
                    <TableContainer component={Paper}>
                      <Table sx={{ minWidth: 650 }} aria-label="simple table">
                        <TableHead>
                          <TableRow>
                            <TableCell>View</TableCell>
                            <TableCell>
                              <span>Sent Time</span>
                            </TableCell>
                            <TableCell>
                              <span>Sent To</span>
                            </TableCell>
                            <TableCell>
                              <span>Type</span>
                            </TableCell>
                            <TableCell>
                              <span>From</span>
                            </TableCell>
                            <TableCell>
                              <span>Subject</span>
                            </TableCell>
                            <TableCell>
                              <span>Sent By</span>
                            </TableCell>
                            <TableCell>Sent OK</TableCell>
                          </TableRow>
                        </TableHead>
                        <TableBody>
                          {itemsInActive?.map(element => {
                            return (
                              <TableRow key={element?._id}>
                                <TableCell>
                                  <SearchOutlinedIcon
                                    onClick={() => {
                                      navigate(
                                        `/edit-enquiries/${id}/email?type=view&email=${element?._id}`,
                                      );
                                    }}
                                  />
                                </TableCell>
                                <TableCell>
                                  {moment(element?.created_at).format(
                                    ' DD/MM/YY h:mm:ss',
                                  )}{' '}
                                </TableCell>
                                <TableCell>{element?.sent_to}</TableCell>
                                <TableCell>{element?.type}</TableCell>
                                <TableCell>
                                  {element?.from_name}{' '}
                                  <span className="d-block">
                                    ({element?.from_email})
                                  </span>
                                </TableCell>
                                <TableCell>
                                  <p className="description">
                                    {element?.subject}
                                  </p>
                                </TableCell>
                                <TableCell>{element?.sent_by}</TableCell>
                                <TableCell>
                                  {element?.sent_ok === true ? (
                                    <img src={CheckIcon} alt="Check Icon" />
                                  ) : (
                                    <img src={CrossIcon} alt="Check Icon" />
                                  )}
                                </TableCell>
                              </TableRow>
                            );
                          })}
                        </TableBody>
                      </Table>
                    </TableContainer>
                  </>
                ) : (
                  'There are currently no previous emails listed as sent against this booking'
                )}
              </div> */}
              <PreviousSentEmails pages={pages} id={id} />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LegacyNotes;
